import EventEmitter from 'eventemitter3';

import { TCombinedEvents } from './events';

/**
 * Wrapper class to re-create the api of the international events for legacy support after we've switched back to eventEmitter3
 */
export class LegacyEvent {
    private eventName: keyof TCombinedEvents;

    constructor(eventName: keyof TCombinedEvents) {
        this.eventName = eventName;
    }

    // eslint-disable-next-line
    public dispatch(...args: any[]): void {
        // eslint-disable-next-line
        eventEmitter.emit(this.eventName, ...args as any);
    }

    // eslint-disable-next-line
    public addListener(listener: (...args: any[]) => void, context?: unknown): void {
        eventEmitter.on(this.eventName, listener, context);
    }

    // eslint-disable-next-line
    public addListenerOnce(listener: (...args: any[]) => void, context?: unknown): void {
        eventEmitter.once(this.eventName, listener, context);
    }

    // eslint-disable-next-line
    public removeListener(listener: (...args: any[]) => void): void {
        eventEmitter.off(this.eventName, listener);
    }
}

export class BasePackageEventEmitter extends EventEmitter<TCombinedEvents> {}

export const eventEmitter = new BasePackageEventEmitter();
